css:
.loader {
  position: relative;
  width: 48px;
  height: 46px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 20px;
  border-radius: 4px 4px 2px 2px;
  background: #6366f1;
}
.loader::after {
  content: "";
  position: absolute;
  top: 16px;
  left: 8px;
  right: 8px;
  height: 4px;
  background: #312e81;
  border-radius: 2px;
  z-index: 3;
}
.loader i {
  position: absolute;
  top: 18px;
  left: 9px;
  width: 30px;
  border: 1px solid #c7d2fe;
  box-sizing: border-box;
  background-color: #eef2ff;
  background-image: repeating-linear-gradient(#c7d2fe 0 2px, transparent 2px 6px);
  background-repeat: no-repeat;
  animation: feed 1.9s ease-in-out infinite;
}
@keyframes feed {
  0% { height: 0; opacity: 1; }
  70% { height: 26px; opacity: 1; }
  100% { height: 26px; opacity: 0; }
}
